-- Satsuei ({{ mode }}): its colours in Hyprland. Generated by rice-render
-- from the plate's overlay; hypr.lua loads it, and `rice recolour` sends it
-- on its own (hyprctl eval) when satsuei-wall sets a new wallpaper.

-- the focused window: the plate's accent running into its second accent
local lit = {
    colors = { "{{ colors.accent | hypr(ee) }}", "{{ colors.accent2 | hypr(ee) }}" },
    angle  = {{ gradient.angle }},
}
-- the rest: a faint light rim, like the glass's
local edge = "{{ colors.fg | hypr(29) }}"

hl.config({
    general = {
        col = {
            active_border   = lit,
            inactive_border = edge,
        },
    },

    decoration = {
        -- nothing goes see-through for losing focus: browsers and Electron
        -- apps stay solid; the glassy tag's windows are frosted (hypr.lua)
        inactive_opacity = 1.0,
        blur = {
            brightness = {{ meta.hypr_blur_brightness }},
            vibrancy   = {{ meta.hypr_blur_vibrancy }},
        },
        -- large and soft, in the plate's darkest
        shadow = {
            range          = 30,
            color          = "{{ colors.ink | hypr(88) }}",
            color_inactive = "{{ colors.ink | hypr(55) }}",
        },
    },

    group = {
        col = {
            border_active   = lit,
            border_inactive = edge,
        },
        groupbar = {
            text_color          = "{{ roles.fg | hypr(ff) }}",
            text_color_inactive = "{{ roles.muted | hypr(ff) }}",
            col = {
                active   = "{{ roles.selection | hypr(ee) }}",
                inactive = "{{ roles.surface | hypr(cc) }}",
            },
        },
    },

    misc = { background_color = "{{ colors.ink | hypr(ff) }}" },
})
